117	/** Moves the claim to the action's status, refusing a change its current status does not allow.
118	 *  Opening gives the claim its number (see {@link ClaimNumbers}); a voided claim keeps it (and it is never reused).
119	 *  Settling fixes the claim's due at the figure it has then: the one its person's last statement
120	 *  bound it to, else its person's grade's rate in force on the claim's date, at least the sheet's floor, plus its late charge then; with no rate it stays live. The user who opened a claim may not settle it.
121	 *  When a clerk settles a claim whose due is over the sheet's clerk limit (a due of n/a is within any
122	 *  limit) it goes PENDING instead, its due still live; a steward settles anything. Only a steward
123	 *  approves a PENDING claim (it settles, its due fixed at its live figure then, plus its late charge),
124	 *  and never the user who opened it; a rejection sends it back to OPEN, bound again by the last
125	 *  statement if that bound it.
126	 *  A deferred claim cannot be settled until the sheet's today reaches its deferred-until date.
127	 *  A claim dated in a closed period cannot change status at all. */
128	public class ApplyClaimStatus {
129	    public void apply(@Val ClaimStatusChange change, @Val Claim claim, ClaimNumbers numbers, People people,
130	            Figures figures, ClosedPeriods closedPeriods, Settings settings)
131	            throws ClaimStatusRefusedException, PeriodClosedException {
132	        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
133	        if (!change.action().allowedFrom(claim.getStatus())) {
134	            throw new ClaimStatusRefusedException(claim.getStatus(), change.action());
135	        }
136	        if (change.action() == ClaimAction.SETTLE && claim.isDeferred()) {
137	            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
138	        }
139	        if (change.action() == ClaimAction.SETTLE && claim.getOpenedBy() != null
140	                && claim.getOpenedBy().equals(change.user())) {
141	            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
142	        }
143	        if (change.action() == ClaimAction.APPROVE) {
144	            if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(change.user())) {
145	                throw new ClaimStatusRefusedException("The user who opened a claim cannot approve it");
146	            }
147	            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
148	                throw new ClaimStatusRefusedException("Only a steward can approve a pending claim");
149	            }
150	        }
151	        BigDecimal due = null;
152	        boolean pending = false;
153	        if (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) {
154	            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
155	            // Figures.figure: the bound figure for an OPEN claim, the live one for a PENDING claim.
156	            due = figures.figure(claim, grade);
157	            if (due != null) due = due.add(figures.charge(claim, due));
158	            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
159	            pending = change.action() == ClaimAction.SETTLE && limit != null && due != null && due.compareTo(limit) > 0
160	                    && settings.role(claim.getSheetId(), change.user()) == Role.CLERK;
161	        }
162	        claim.setStatus(pending ? ClaimStatus.PENDING : change.action().to());
163	        if (change.action() == ClaimAction.OPEN) {
164	            claim.setNumber(numbers.next(claim));
165	            claim.setOpenedBy(change.user());
166	        }
167	        if ((change.action() == ClaimAction.SETTLE && !pending) || change.action() == ClaimAction.APPROVE) {
168	            claim.setDue(due);
169	        }
170	    }
171	}
