449	public record ClaimRequest(String amount, String date, String note, String corrects, String user) {
450	    /** Up to two decimals; negative only for a correction. */
451	    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
452	    private static final Pattern NUMBER = Pattern.compile("\\d+|.+-\\d+");
453	    /** The request's values as the claim rules accept them, or refused. A negative amount is a
454	     *  correction and must name the number of the claim it corrects; any other claim corrects none. */
455	    public static ClaimValues checked(ClaimRequest request) throws InvalidSheetRequestException {
456	        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
457	        if (!AMOUNT.matcher(amount).matches()) {
458	            throw new InvalidSheetRequestException("The amount must be a number with up to two decimals");
459	        }
460	        BigDecimal value = new BigDecimal(amount).setScale(2);
461	        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
462	        String corrects = null;
463	        if (value.signum() < 0) {
464	            if (!NUMBER.matcher(rawCorrects).matches()) {
465	                throw new InvalidSheetRequestException("A negative amount must name the number of the settled claim it corrects");
466	            }
467	            corrects = rawCorrects;
468	        }
469	        String rawDate = request.date() == null ? "" : request.date().trim();
470	        LocalDate date = null;
471	        if (!rawDate.isEmpty()) {
472	            try {
473	                date = LocalDate.parse(rawDate);
474	            } catch (DateTimeParseException e) {
475	                throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + rawDate);
476	            }
477	        }
478	        String note = request.note() == null ? "" : request.note();
