543	    }
544	    /** Whether the person has a SETTLED claim with this number: one a correction may correct. */
545	    public boolean settled(String sheetId, long personId, String number) {
546	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ? AND status = 'SETTLED'",
547	                Integer.class, sheetId, personId, number);
