552	        return jdbc.query("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ?",
553	                (rs, i) -> rs.getDate("claim_date").toLocalDate(), sheetId, personId, number)
554	                .stream().findFirst().orElse(null);
