561	    /** Insert a new claim (assigning its id) or update an existing one. */
562	    public void save(Claim claim) {
563	        if (claim.getId() != null) {
564	            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ?, deferred_until = ? WHERE id = ?",
565	                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
566	                    claim.getNumber(), claim.getDue(), claim.getOpenedBy(), claim.isStated(), claim.getStatedDue(), claim.getCorrects(),
567	                    claim.getDeferredUntil() != null ? Date.valueOf(claim.getDeferredUntil()) : null, claim.getId());
568	            return;
569	        }
570	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
571	        jdbc.update(con -> {
572	            PreparedStatement ps = con.prepareStatement(
573	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, due_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
574	                    new String[] { "id" });
575	            ps.setString(1, claim.getSheetId());
576	            ps.setLong(2, claim.getPersonId());
577	            ps.setBigDecimal(3, claim.getAmount());
578	            ps.setDate(4, Date.valueOf(claim.getDate()));
579	            ps.setString(5, claim.getNote());
580	            ps.setString(6, claim.getStatus().name());
581	            ps.setString(7, claim.getCorrects());
582	            ps.setDate(8, Date.valueOf(claim.getDueBy()));
