586	    }
587	    private static Claim claim(ResultSet rs, int i) throws SQLException {
588	        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
589	                rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
590	                ClaimStatus.valueOf(rs.getString("status")), rs.getString("number"),
591	                rs.getBigDecimal("due"), rs.getString("opened_by"));
592	        claim.setStated(rs.getBoolean("stated"));
593	        claim.setStatedDue(rs.getBigDecimal("stated_due"));
594	        claim.setCorrects(rs.getString("corrects"));
595	        claim.setDueBy(rs.getDate("due_by").toLocalDate());
