647	/** The figure a claim shows and totals: the due fixed when it was settled, else the figure its
648	 *  person's last statement bound it to, else live at its person's grade's rate in force on the
649	 *  claim's date, at least the sheet's floor (null, n/a, when there is no rate). An overdue claim's
650	 *  due adds its late charge on top of that figure. Every rounding of a claim's live figures follows
651	 *  the sheet's policy date: half up for a claim dated before it, half to even on or after it. */
652	@Service
653	public class Figures {
654	    private final Rates rates;
655	    private final Settings settings;
656	    private final Sheets sheets;
657	    private final Claims claims;
658	    public Figures(Rates rates, Settings settings, Sheets sheets, Claims claims) {
659	        this.rates = rates;
660	        this.settings = settings;
661	        this.sheets = sheets;
662	        this.claims = claims;
663	    }
664	    /** The sheet's policy date: as set, else the sheet's today. */
665	    public LocalDate policyDate(String sheetId) {
666	        LocalDate set = settings.policyDate(sheetId);
667	        return set != null ? set : sheets.today(sheetId);
668	    }
669	    /** How the claim's live figures round: half up when the claim is dated before the sheet's policy
670	     *  date, half to even on or after it. A correction rounds by the date of the claim it corrects. */
671	    public RoundingMode rounding(Claim claim) {
672	        return roundingDate(claim).isBefore(policyDate(claim.getSheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
673	    }
674	    /** The date the claim rounds by: its own, or for a correction that of the claim it corrects. */
675	    public LocalDate roundingDate(Claim claim) {
676	        if (claim.getCorrects() == null) return claim.getDate();
677	        LocalDate corrected = claims.dateOf(claim.getSheetId(), claim.getPersonId(), claim.getCorrects());
678	        return corrected != null ? corrected : claim.getDate();
679	    }
680	    /** The claim's due as the screen shows and totals it: its figure, plus its late charge while it
681	     *  is overdue. A settled claim's fixed due already holds the charge it had then. */
682	    public BigDecimal due(Claim claim, String grade) {
683	        BigDecimal figure = figure(claim, grade);
684	        if (figure == null || claim.getDue() != null) return figure;
685	        return figure.add(charge(claim, figure));
686	    }
687	    /** The claim's figure without any late charge: the fixed due, else the bound figure, else live.
688	     *  A PENDING claim is not bound by a statement: it keeps its binding but shows its live figure. */
689	    public BigDecimal figure(Claim claim, String grade) {
690	        if (claim.getDue() != null) return claim.getDue();
691	        if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) return claim.getStatedDue();
692	        return live(claim, grade);
693	    }
694	    /** The late charge on a figure of the claim: nothing unless the claim is OPEN (or PENDING), not deferred, and its due-by (fixed
695	     *  when it was added) is before the sheet's today; then the sheet's late percent of the
696	     *  figure for every full 30 days it is overdue (the late percent in force on the claim's date) (a correction has none), rounded by the claim's rounding to two decimals. Never bound
697	     *  by a statement: it follows the sheet's today. */
698	    public BigDecimal charge(Claim claim, BigDecimal figure) {
699	        BigDecimal none = BigDecimal.ZERO.setScale(2);
700	        if (figure == null || !claim.getStatus().isOpen() || claim.isDeferred() || claim.isCorrection()) return none;
701	        String sheetId = claim.getSheetId();
702	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheets.today(sheetId)) / 30;
703	        if (periods <= 0) return none;
704	        return figure.multiply(settings.latePct(sheetId, claim.getDate())).multiply(BigDecimal.valueOf(periods))
705	                .divide(BigDecimal.valueOf(100)).setScale(2, rounding(claim));
706	    }
707	    /** The claim's due at its person's grade's rate in force on the claim's date: amount times the
708	     *  rate divided by 100, rounded by the claim's rounding to two decimals, raised to the sheet's floor in force on the claim's date when it
709	     *  is below it (a correction has no floor); null when there is no rate. */
710	    public BigDecimal live(Claim claim, String grade) {
711	        BigDecimal pct = rates.pct(claim.getSheetId(), grade, claim.getDate());
712	        if (pct == null) return null;
713	        BigDecimal due = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100)).setScale(2, rounding(claim));
714	        return claim.isCorrection() ? due : due.max(settings.floor(claim.getSheetId(), claim.getDate()));
715	    }
716	}
