748	/** Opens each selected claim that can be opened, in list order (people in list order, each
749	 *  person's newest claim first), so their numbers follow that order. Each is opened as a single
750	 *  open would be — its own audit line, then the figures it moved; one that cannot be opened (or is
751	 *  not on the sheet) is left as it is and counted as refused. */
752	public class OpenClaims {
753	    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpen bulk, Claims claims, People people,
754	            ClaimNumbers numbers, Figures figures, ClosedPeriods closedPeriods, Settings settings, Rollup rollup,
755	            ClaimLog log, Audit audit, Out<BulkOpenResult> result) {
756	        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.OPEN, bulk.user());
757	        ApplyClaimStatus apply = new ApplyClaimStatus();
758	        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
759	        List<Claim> all = claims.onSheet(sheetId);
760	        int opened = 0;
761	        for (Person person : people.onSheet(sheetId)) {
762	            for (Claim listed : all) {
763	                if (listed.getPersonId() != person.getId() || !bulk.claimIds().contains(listed.getId())) continue;
764	                Claim claim = claims.find(sheetId, listed.getId());
765	                Snapshot before = rollup.snapshot(sheetId);
766	                try {
767	                    apply.apply(change, claim, numbers, people, figures, closedPeriods, settings);
768	                } catch (ClaimStatusRefusedException | PeriodClosedException e) {
769	                    continue;
770	                }
771	                claims.save(claim);
772	                record.record(change, claim, people, log, audit);
773	                rollup.record(sheetId, before, bulk.user());
774	                opened++;
775	            }
776	        }
777	        result.set(new BulkOpenResult(opened, bulk.claimIds().size() - opened));
778	    }
779	}
