921	/** Settles each selected claim that can be settled, in list order (people in list order, each
922	 *  person's newest claim first), by the signed-in user. Each is settled as a single settle would
923	 *  be — its own audit line, then the figures it moved; one that goes PENDING counts as settled. One
924	 *  that cannot be settled (or is not on the sheet) is left as it is and counted as refused. */
925	public class SettleClaims {
926	    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettle bulk, Claims claims, People people,
927	            ClaimNumbers numbers, Figures figures, ClosedPeriods closedPeriods, Settings settings, Rollup rollup,
928	            ClaimLog log, Audit audit, Out<BulkSettleResult> result) {
929	        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.SETTLE, bulk.user());
930	        ApplyClaimStatus apply = new ApplyClaimStatus();
931	        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
932	        List<Claim> all = claims.onSheet(sheetId);
933	        int settled = 0;
934	        for (Person person : people.onSheet(sheetId)) {
935	            for (Claim listed : all) {
936	                if (listed.getPersonId() != person.getId() || !bulk.claimIds().contains(listed.getId())) continue;
937	                Claim claim = claims.find(sheetId, listed.getId());
938	                Snapshot before = rollup.snapshot(sheetId);
939	                try {
940	                    apply.apply(change, claim, numbers, people, figures, closedPeriods, settings);
941	                } catch (ClaimStatusRefusedException | PeriodClosedException e) {
942	                    continue;
943	                }
944	                claims.save(claim);
945	                record.record(change, claim, people, log, audit);
946	                rollup.record(sheetId, before, bulk.user());
947	                settled++;
948	            }
949	        }
950	        result.set(new BulkSettleResult(settled, bulk.claimIds().size() - settled));
