=== claim/AddPastedClaims.java
/** Builds every pasted claim first, as the claim form would for its named person, so one refused
 *  line refuses the whole paste before anything is saved; then saves and audits each in order. */
public class AddPastedClaims {
    public void add(@PathVariable("sheetId") String sheetId, @Val PastedClaims paste, People people, Sheets sheets,
            ClosedPeriods closedPeriods, Claims claims, Settings settings, ClaimLog log, Audit audit,
            Out<PasteClaimsResult> result) throws PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        List<Person> persons = new ArrayList<>();
        List<Claim> built = new ArrayList<>();
        for (PastedLine line : paste.lines()) {
            Person person = people.named(sheetId, line.name());
            if (person == null) throw new InvalidSheetRequestException("No one on the sheet is named " + line.name());
            persons.add(person);
            built.add(BuildClaim.built(line.values(), person, sheets, closedPeriods, claims, settings));
        }
        RecordClaimAdded record = new RecordClaimAdded();
        for (int i = 0; i < built.size(); i++) {
            claims.save(built.get(i));
            record.record(paste.lines().get(i).values(), persons.get(i), built.get(i), log, audit);
        }
        result.set(new PasteClaimsResult(built.size()));
    }
}
=== claim/ApplyClaimDefer.java
/** Defers an OPEN claim until a date after the sheet's today (a deferred one may be deferred again).
 *  A claim not OPEN, a date not after today, or a claim dated in a closed period is refused. */
public class ApplyClaimDefer {
    public void apply(@Val ClaimDefer change, @Val Claim claim, Sheets sheets, ClosedPeriods closedPeriods)
            throws ClaimStatusRefusedException, PeriodClosedException {
        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ClaimStatusRefusedException("Only an OPEN claim can be deferred");
        }
        if (!change.until().isAfter(sheets.today(claim.getSheetId()))) {
            throw new ClaimStatusRefusedException("A claim can only be deferred to a date after the sheet's today");
        }
        claim.setDeferredUntil(change.until());
        claim.setDeferred(true);
    }
}
