132	                (ResultSet rs) -> {
133	                    grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
134	                            .put(fromKey(rs.getDate("from_date")), rs.getString("grade"));
135	                }, sheetId);
