183	            if (dated != null) saveGrade(person, dated);
184	            return true;
185	        }
186	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
187	        jdbc.update(con -> {
188	            PreparedStatement ps = con.prepareStatement(
189	                    "INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)", new String[] { "id" });
190	            ps.setString(1, person.getSheetId());
191	            ps.setString(2, person.getName());
192	            ps.setString(3, person.getFirstGrade());
193	            return ps;
194	        }, keys);
195	        person.setId(keys.getKey().longValue());
196	        // The first grade a person is given applies from the beginning of time.
197	        saveGrade(person, new Person.DatedGrade(person.getFirstGrade(), null));
198	        return true;
