525	/** Takes the person's statement: their due-total now, the sum of their counting claims' figures
526	 *  with any late charges (n/a when there is no rate today and none has a figure), at most the sheet's cap, dated the sheet's today. Every claim
527	 *  of theirs that counts (not an OPEN one dated within one of their holds) is bound to the figure it has now, without its late charge; every other one is unbound. */
528	public class TakeStatement {
529	    public void take(@Val StatementRequest request, @Val Person person, Claims claims, Figures figures,
530	            Rates rates, Sheets sheets, Settings settings, People people, Out<Statement> statement) {
531	        Person locked = people.lock(person.getSheetId(), person.getId());
532	        person.setStatementCount(locked.getStatementCount());
533	        BigDecimal total = BigDecimal.ZERO.setScale(2);
534	        boolean any = false;
535	        int counted = 0;
536	        for (Claim claim : claims.ofPerson(person.getSheetId(), person.getId())) {
537	            if (person.counts(claim)) {
538	                BigDecimal bound = figures.figure(claim, person.gradeOn(claim.getDate()));
539	                // The statement binds the figure; the late charge on top keeps following today.
540	                BigDecimal figure = bound == null || claim.getDue() != null ? bound : bound.add(figures.charge(claim, bound));
541	                claim.setStated(true);
542	                claim.setStatedDue(bound);
543	                counted++;
544	                if (figure != null) {
545	                    total = total.add(figure);
546	                    any = true;
547	                }
548	            } else {
549	                claim.setStated(false);
550	                claim.setStatedDue(null);
551	            }
552	            claims.save(claim);
553	        }
554	        var today = sheets.today(person.getSheetId());
555	        BigDecimal dueTotal = !any && rates.pct(person.getSheetId(), person.gradeOn(today), today) == null ? null
556	                : settings.capped(person.getSheetId(), total);
557	        person.setStatementCount(person.getStatementCount() + 1);
558	        person.setStatedTotal(dueTotal);
559	        person.setStatementDate(today);
560	        people.saveStatement(person);
561	        statement.set(new Statement(dueTotal, counted, request.user()));
562	    }
563	}
