25	public class ClosePeriod {
26	    public void close(@Val Period period, Periods periods, Claims claims, People people, Figures figures,
27	            Out<ClosedPeriod> closed) throws PeriodClosedException {
28	        if (period.closed()) throw new PeriodClosedException("Period " + period.name() + " is already closed");
29	        Map<Long, Person> personOf = people.onSheet(period.sheetId()).stream()
30	                .collect(Collectors.toMap(Person::getId, p -> p));
31	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
32	        for (Long id : personOf.keySet()) personTotals.put(id, BigDecimal.ZERO.setScale(2));
33	        for (Claim claim : claims.onSheet(period.sheetId())) {
34	            if (!period.contains(claim.getDate())) continue;
35	            Person person = personOf.get(claim.getPersonId());
36	            if (person == null || !person.counts(claim)) continue;
37	            BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
38	            if (figure != null) personTotals.merge(person.getId(), figure, BigDecimal::add);
39	        }
40	        BigDecimal total = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
41	        periods.close(period, total, personTotals);
42	        closed.set(new ClosedPeriod(new Period(period.sheetId(), period.name(), period.from(), period.to(), true, total)));
43	    }
