717	/**
718	 * The figures the screen shows — each person's claimed and due-total, the sheet's claimed-total and
719	 * due-total, and each one's overdue-total and the sheet's — worked out as the screen does, so a change can audit the ones it moved: one ROLLUP
720	 * line per person whose figures changed (a new person counts as changed), then a TOTALS line when
721	 * the sheet's totals changed.
722	 */
723	@Service
724	public class Rollup {
725	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
726	    private final People people;
727	    private final Claims claims;
728	    private final Figures figures;
729	    private final Rates rates;
730	    private final Sheets sheets;
731	    private final Audit audit;
732	    private final Settings settings;
733	    public Rollup(People people, Claims claims, Figures figures, Rates rates, Sheets sheets, Audit audit, Settings settings) {
734	        this.people = people;
735	        this.claims = claims;
736	        this.figures = figures;
737	        this.rates = rates;
738	        this.sheets = sheets;
739	        this.audit = audit;
740	        this.settings = settings;
741	    }
742	    /** The sheet's figures now. A person's due-total is the sum of their counting claims' figures (a
743	     *  person's OPEN claims dated within a hold of theirs do not count, unless a statement binds them),
744	     *  n/a when there is no rate today and none has a figure, at most the sheet's cap (n/a is not
745	     *  capped); the sheet's skips the n/a ones. */
746	    public Snapshot snapshot(String sheetId) {
747	        LocalDate today = sheets.today(sheetId);
748	        List<Claim> all = claims.onSheet(sheetId);
749	        Map<Long, Snapshot.PersonFigures> figuresOf = new LinkedHashMap<>();
750	        BigDecimal claimedTotal = ZERO;
751	        BigDecimal dueTotal = ZERO;
752	        BigDecimal overdueTotal = ZERO;
753	        for (Person person : people.onSheet(sheetId)) {
754	            BigDecimal claimed = ZERO;
755	            BigDecimal due = ZERO;
756	            BigDecimal overdue = ZERO;
757	            boolean any = false;
758	            for (Claim claim : all) {
759	                if (claim.getPersonId() != person.getId() || !person.counts(claim)) continue;
760	                claimed = claimed.add(claim.getAmount());
761	                BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
762	                if (figure != null) {
763	                    due = due.add(figure);
764	                    any = true;
765	                    if (claim.getStatus().isOpen() && !claim.isDeferred() && today != null && claim.getDueBy().isBefore(today)) {
766	                        overdue = overdue.add(figure);
767	                    }
768	                }
769	            }
770	            if (!any && rates.pct(sheetId, person.gradeOn(today), today) == null) due = null;
771	            due = settings.capped(sheetId, due);
772	            figuresOf.put(person.getId(), new Snapshot.PersonFigures(person.getName(), claimed, due, overdue));
773	            claimedTotal = claimedTotal.add(claimed);
774	            if (due != null) dueTotal = dueTotal.add(due);
775	            overdueTotal = overdueTotal.add(overdue);
776	        }
777	        return new Snapshot(figuresOf, claimedTotal, dueTotal, overdueTotal);
778	    }
