780	    public void record(String sheetId, Snapshot before, String user) {
781	        Snapshot after = snapshot(sheetId);
782	        String prefix = " sheet=" + sheetId + " by=" + user;
783	        after.people().forEach((id, now) -> {
784	            Snapshot.PersonFigures was = before.people().get(id);
785	            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
786	                    && same(was.overdueTotal(), now.overdueTotal())) return;
787	            audit.record("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + show(now.claimed())
788	                    + " due-total=" + show(now.dueTotal()) + " overdue-total=" + show(now.overdueTotal()));
789	        });
790	        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())
791	                || !same(before.overdueTotal(), after.overdueTotal())) {
792	            audit.record("TOTALS" + prefix + " claimed-total=" + show(after.claimedTotal())
793	                    + " due-total=" + show(after.dueTotal()) + " overdue-total=" + show(after.overdueTotal()));
794	        }
795	    }
796	    private static boolean same(BigDecimal a, BigDecimal b) {
797	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
798	    }
799	    private static String show(BigDecimal value) {
800	        return value == null ? "n/a" : value.setScale(2).toPlainString();
801	    }
