950	/**
951	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
952	 * so tests can assert side-effects by reading that file — the second test-assertion channel
953	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
954	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
955	 *
956	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
957	 * SYNC) so a test reads the record immediately.
958	 */
959	@Service
960	public class Audit {
961	    private final Path file;
962	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
963	        this.file = Path.of(path);
964	    }
965	    /** Append one audit record. Tests assert the exact line(s) in the file. */
966	    public synchronized void record(String entry) {
967	        try {
968	            Path parent = file.toAbsolutePath().getParent();
969	            if (parent != null) {
970	                Files.createDirectories(parent);
971	            }
972	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
973	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
974	        } catch (IOException e) {
975	            throw new UncheckedIOException(e);
976	        }
977	    }
978	    /** Remove the audit file. */
979	    public synchronized void clear() {
980	        try {
981	            Files.deleteIfExists(file);
982	        } catch (IOException e) {
983	            throw new UncheckedIOException(e);
984	        }
985	    }
986	}
